void Editor::initializeShortcuts(){if(!smoke_)try{const auto file=palettePreferencePath().parent_path()/"shortcuts-v2.json";if(std::filesystem::exists(file)){if(std::filesystem::file_size(file)>1024*1024)throw std::runtime_error("Shortcut JSON exceeds 1 MiB");std::ifstream in(file,std::ios::binary);if(!in)throw std::runtime_error("Cannot read shortcut settings");std::ostringstream text;text<<in.rdbuf();shortcutBindings_=shortcuts::decode(text.str());}}catch(const std::exception& e){shortcutReadable_=false;status_=U"快捷键读取失败："+unicodeText(e.what());}menuCommands_.bind("openShortcutSettings",{[this]{showShortcutSettings();},[this]{return pending_==Pending::None;},{}});shortcutDeferredTimer_.Tick.connect([this]{if(pending_!=Pending::None||historyGestureBusy())return;if(deferredShortcuts_.empty()){shortcutDeferredTimer_.stop();return;}const auto next=deferredShortcuts_.front();deferredShortcuts_.erase(deferredShortcuts_.begin());if(documentOpen_&&next.first==document.identity())runShortcutCommand(next.second);if(deferredShortcuts_.empty())shortcutDeferredTimer_.stop();});syncShortcutLabels();}
