void Editor::showShortcutSettings(bool verify){if(pending_!=Pending::None||shortcutDialogOpen_)return;ShortcutDialog popup(font_,skin_,toolIcons_,shortcutBindings_,[this](const std::string& id){return shortcutSupported(id);},[this](const shortcuts::Bindings& values){return saveShortcuts(values);},[this]{return shortcutImportFile();},[this](const std::string& text){shortcutExportFile(text);});popup.setDisplay(display(),false);const auto r=uiLogical(bounds());popup.setBounds(toDisplay({r.x+std::max(0,(r.w-520)/2),r.y+std::max(0,(r.h-380)/2),520,380}));ui::Timer timer(120,&popup);std::exception_ptr error;int stage=0;if(verify){timer.Tick.connect([&]{try{if(stage++==0){popup.smoke();return;}timer.stop();writeSmokeFrame(popup.display()->nativeSurface().get(),assets_.parent_path()/"shortcut-settings-smoke.bmp");popup.closeWindow(nullptr);}catch(...){error=std::current_exception();timer.stop();popup.closeWindow(nullptr);}});timer.start();}shortcutDialogOpen_=true;popup.openWindowInForeground();shortcutDialogOpen_=false;timer.stop();refresh();requestFocus();if(error)std::rethrow_exception(error);}

